    MOD = 10**9 + 7

    # dp[i][j] will store the number of ways to arrange i+j balls with i blue balls
    # such that Takahashi needs exactly j moves to collect all blue balls.
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: 1 way to arrange 0 balls (empty arrangement)
    dp[0][0] = 1

    for total_balls in range(1, N + 1):
        for blue_balls in range(min(total_balls, K) + 1):
            red_balls = total_balls - blue_balls

            # If we add a red ball, it doesn't change the number of moves needed
